package com.shopsphere.web;
import com.shopsphere.dao.AdminReviewDAO;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;
@WebServlet("/admin/reviews") public class AdminReviewServlet extends HttpServlet{private final AdminReviewDAO dao=new AdminReviewDAO();protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{try{q.setAttribute("reviews",dao.findAll());q.getRequestDispatcher("/WEB-INF/views/admin/reviews.jsp").forward(q,p);}catch(Exception e){throw new ServletException("Unable to load reviews",e);}}protected void doPost(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{try{dao.delete(Integer.parseInt(q.getParameter("reviewId")));p.sendRedirect(q.getContextPath()+"/admin/reviews");}catch(NumberFormatException e){p.sendError(400,"Invalid review id");}catch(Exception e){throw new ServletException("Unable to moderate review",e);}}}
